const markTheoryRefuted = `-- name: MarkTheoryRefuted :execrows
UPDATE theories t SET status = 'refuted', refuted_by_response_id = r.id, refuted_by_user_id = r.user_id, refuted_at = NOW()
FROM responses r
WHERE t.id = $1 AND r.id = $2 AND r.theory_id = t.id AND r.parent_id IS NULL AND r.side = 'without_love' AND r.user_id <> t.user_id AND t.status <> 'refuted'
`

type MarkTheoryRefutedParams struct {
	ID   uuid.UUID
	ID_2 uuid.UUID
}

func (q *Queries) MarkTheoryRefuted(ctx context.Context, arg MarkTheoryRefutedParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, markTheoryRefuted, arg.ID, arg.ID_2)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const recomputeTheoryStatus = `-- name: RecomputeTheoryStatus :exec
UPDATE theories t SET status = CASE
    WHEN EXISTS (SELECT 1 FROM responses r WHERE r.theory_id = t.id AND r.parent_id IS NULL) THEN 'contested'::theory_status
    ELSE 'open'::theory_status
END
WHERE t.id = $1 AND t.status <> 'refuted'
`

func (q *Queries) RecomputeTheoryStatus(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.ExecContext(ctx, recomputeTheoryStatus, id)
	return err
}

